package com.pharmapack.qms.master; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="materials") @Getter @Setter @NoArgsConstructor public class Material { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="material_code",nullable=false,unique=true) String materialCode; @Column(name="material_name",nullable=false) String materialName; @Column(name="material_type",nullable=false) String materialType; @Column(nullable=false) String uom; String status="ACTIVE"; }